[Rewrite]
# 感谢【向晚】分享
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/search\/firstPage\/getPromptList\/v1\?.*/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: [] }")
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/benefits\/benefitsCard\/getInfo\/v1\?.*/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: [] }")
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/content\/booth\/getBoothList\/v1\?.*showPositionCode=VWAPP_HOME_BUOY/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: [] }")
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/content\/booth\/getBoothList\/v1\?.*showPositionCode=VWAPP_(ICE|MEB)_(OPEN_SCREEN_ADS|CAR_ZHIHU_COLLEGE)/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: [] }")
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/content\/booth\/getBoothList\/v1\?.*showPositionCode=VWAPP_(ICE|MEB)_HOME_(OWNER_BANNER|PROSPECTS_BANNER|CUSTOM_BANNER|KONGO|CUSTOM_KONGO)/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: [] }")
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/content\/(customize\/getCustomizePageName|recommend\/getRecommendInfoFlows|activity\/getSquareActivityList|theme\/getThemeList|post\/getPostsByTags|evaluate\/getEvaluateCards)\/v1\?.*/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: [] }")
response if ${url} ~= /^https?:\/\/oneapp-api\.faw-vw\.com\/content\/(collection\/getCollectionList)\/v1\?.*/i then response.json.jq(". = { returnStatus: \"SUCCEED\", hasMore: false, data: {} }")


[MITM]
hostname = oneapp-api.faw-vw.com
